### Classic UI Positions Candidate Window Using Cursor Rect

Source: https://github.com/fcitx/fcitx5/blob/master/src/ui/classic/xcbinputwindow.cpp

ClassicUI watches CursorRectChangedEvent and calls updateCursor, which calls XCBInputWindow::updatePosition. This method reads the cursor rectangle from the input context (originally set via DBus), finds the closest screen, and configures the X11 window position relative to the cursor.

```cpp
// classicui.cpp: watches cursor rect change events
    eventHandlers_.emplace_back(instance_->watchEvent(
        EventType::InputContextCursorRectChanged, EventWatcherPhase::Default,
        [this](Event &event) {
            if (auto *ui = uiForEvent(event)) {
                auto &icEvent = static_cast<InputContextEvent &>(event);
                ui->updateCursor(icEvent.inputContext());
            }
        }));

// xcbinputwindow.cpp: positions window using cursorRect
void XCBInputWindow::updatePosition(InputContext *inputContext) {
    if (!visible()) {
        return;
    }

    const Rect &cursorRect = inputContext->cursorRect();
    const Rect *closestScreen = getClosestScreen(cursorRect);
    xcb_params_configure_window_t wc;
    wc.x = calculatePositionX(cursorRect, closestScreen);
    wc.y = calculatePositionY(cursorRect, closestScreen);
    wc.stack_mode = XCB_STACK_MODE_ABOVE;
    xcb_aux_configure_window(ui_->connection(), wid_,
                             XCB_CONFIG_WINDOW_STACK_MODE |
                                 XCB_CONFIG_WINDOW_X | XCB_CONFIG_WINDOW_Y,
                             &wc);
}
```

